import pytest


def age_at(born: int, now: int) -> int:
    """Whole years from the birth year `born` to the current year `now`.

    The current year is supplied by the caller; this function never reads
    the system clock. Raises ValueError if `now` is earlier than `born`.
    """
    if now < born:
        raise ValueError(f"current year {now} is before birth year {born}")
    return now - born


def test_age_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_counts_whole_years() -> None:
    assert age_at(2000, 2024) == 24


def test_age_one_year_later() -> None:
    assert age_at(1999, 2000) == 1


def test_age_before_birth_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2000, 1999)
